// 0x1cff97c Phigros2.Chapter9.Chapter9Phase1Control$$.cctor
0x1cff9a4: bl       #0x1b64570 | 
0x1cff9b0: bl       #0x1b64570 | 
0x1cff9bc: bl       #0x1b64570 | 
0x1cff9c4: ldr      x0, [x0, #0x6c8] | 0x418a6c8 '混沌の中、真実の幻影が次第に形を結び始める。この先、一体何が二人を待ち受けているのだろうか？'
0x1cff9c8: bl       #0x1b64570 | 
0x1cff9d0: ldr      x0, [x0, #0x6d0] | 0x418a6d0 '그들이 그토록 갈망하던 진실이 있는 곳을 향해 걸어갔다.'
0x1cff9d4: bl       #0x1b64570 | 
0x1cff9dc: ldr      x0, [x0, #0x6d8] | 0x418a6d8 '"Do I just hold it, or do I need to do something?"\r\n"Theoretically it activates on its own; just take it out and hold it. Still, we can\'t guarantee that everything it attracts is our data. <b><color=#00e4ff>Human</color></b> brains, you know - getting out cleanly isn\'t that easy. But it won\'t be dangerous, at least."'
0x1cff9e0: bl       #0x1b64570 | 
0x1cff9e8: ldr      x0, [x0, #0x6e0] | 0x418a6e0 '向著他們渴望的真相所在之處走去。'
0x1cff9ec: bl       #0x1b64570 | 
0x1cff9f4: ldr      x0, [x0, #0x6e8] | 0x418a6e8 'そして、野営地が夜の眠りに包まれる中、'
0x1cff9f8: bl       #0x1b64570 | 
0x1cffa00: ldr      x0, [x0, #0x6f0] | 0x418a6f0 "'그냥 들고 있으면 되는 거야, 아니면 무슨 조작이 필요한 거야?'\r\n'이론상 이건 자동으로 작동해. 꺼내서 손에 쥐고 있기만 하면 돼. 다만 이게 끌어오는 게 전부 우리 데이터라고는 장담할 수 없어. 인간의 뇌라니까. 알잖아. 깨끗하게 빼내는 게 그리 쉽지는 않거든. 그래도 위험한 일은 아니야.'"
0x1cffa04: bl       #0x1b64570 | 
0x1cffa0c: ldr      x0, [x0, #0x6f8] | 0x418a6f8 '眠らぬ二人は、先人たちの辿った道へと踏み出した。'
0x1cffa10: bl       #0x1b64570 | 
0x1cffa18: ldr      x0, [x0, #0x700] | 0x418a700 'Thus, the camp slept on through the night,'
0x1cffa1c: bl       #0x1b64570 | 
0x1cffa24: ldr      x0, [x0, #0x708] | 0x418a708 '曾經的她，在像素塔中用自己關於“隼”的記憶，製造了一個新的“隼”。但如今，這個隼已經被污染得面目全非，不再是她記憶裡的兄長，而是一個獨立存在的“<b><color=#00e4ff>人類</color></b>”，以至於她不再認識他，甚至放棄了繼續維持他的存在。\r\n“你在哪……”'
0x1cffa28: bl       #0x1b64570 | 
0x1cffa30: ldr      x0, [x0, #0x710] | 0x418a710 '七百七十年過去，塔組織已達到了模擬目標，他們決定保存數據，關閉像素塔，以防技術洩漏。於是，他們啟動了像素塔的清掃程序——幽藍邊界。\r\n吞噬一切的境界線下，<b><color=#00e4ff>人類</color></b>建起的巴別塔再次倒塌。'
0x1cffa34: bl       #0x1b64570 | 
0x1cffa3c: ldr      x0, [x0, #0x718] | 0x418a718 '混沌之中，真相的虛影凝結，等待著二人的，又會是什麼？'
0x1cffa40: bl       #0x1b64570 | 
0x1cffa48: ldr      x0, [x0, #0x720] | 0x418a720 'Open'
0x1cffa4c: bl       #0x1b64570 | 
0x1cffa54: ldr      x0, [x0, #0x728] | 0x418a728 '兩道身影清醒著，踏上先驅者曾走過的路，'
0x1cffa58: bl       #0x1b64570 | 
0x1cffa60: ldr      x0, [x0, #0x730] | 0x418a730 'walking towards the place where their long-sought truth awaited.'
0x1cffa64: bl       #0x1b64570 | 
0x1cffa6c: ldr      x0, [x0, #0x738] | 0x418a738 '“只要拿着就可以吗，还是说需要进行某些操作？”\r\n“理论上说这东西是自动生效的，掏出来捏手里就行。不过，我们不能保证它吸引来的完全都是我们的数据，毕竟<b><color=#00e4ff>人类</color></b>的大脑嘛——你懂得，缠点儿什么，避免不了。”'
0x1cffa70: bl       #0x1b64570 | 
0x1cffa78: ldr      x0, [x0, #0x740] | 0x418a740 '770년이 흐른 뒤, 탑 조직은 시뮬레이션의 목표에 도달했다. 그들은 기술 유출을 막기 위해 데이터를 보존하고 픽셀 타워를 폐쇄하기로 결정했다. 그리고 픽셀 타워의 정리 프로그램——마자린 엔드——를 가동했다.\r\n모든 것을 집어삼키는 경계선 아래에서, <b><color=#00e4ff>인간</color></b>들이 세운 바벨탑은 다시 무너져 내렸다.'
0x1cffa7c: bl       #0x1b64570 | 
0x1cffa84: ldr      x0, [x0, #0x748] | 0x418a748 'Once, inside the Pixel Tower, she had used her memories of "Peregrinus" to create a new "Peregrinus." But now, that Peregrinus had been corrupted beyond recognition - no longer the brother she remembered, but an independent "<b><color=#00e4ff>human</color></b>" - she could no longer recognize him, and had even given up maintaining his existence.\r\n"Where is the real you..."'
0x1cffa88: bl       #0x1b64570 | 
0x1cffa90: ldr      x0, [x0, #0x750] | 0x418a750 'From the swirling chaos, the shadowy phantom of truth begins to take shape. What fate, then, lies in wait for them both?'
0x1cffa94: bl       #0x1b64570 | 
0x1cffa9c: ldr      x0, [x0, #0x758] | 0x418a758 '두 사람만이 깨어 선구자들이 걸었던 길에 발을 내디뎠다.'
0x1cffaa0: bl       #0x1b64570 | 
0x1cffaa8: ldr      x0, [x0, #0x760] | 0x418a760 '向着他们渴望的真相所在之处走去。'
0x1cffaac: bl       #0x1b64570 | 
0x1cffab4: ldr      x0, [x0, #0x768] | 0x418a768 '于是，那一夜的营地继续沉睡，'
0x1cffab8: bl       #0x1b64570 | 
0x1cffac0: ldr      x0, [x0, #0x770] | 0x418a770 'while two wakeful souls embarked upon the path trodden by forerunners,'
0x1cffac4: bl       #0x1b64570 | 
0x1cffacc: ldr      x0, [x0, #0x778] | 0x418a778 '「手に持っているだけでいいのか？ それとも何か操作が必要か？」\r\n「理論上は自動で効力を発揮するはずだ、取り出して手に握っていればいい。ただ、引き寄せられるものが100%我々のデータだけとは保証できないがね。なにせ<b><color=#00e4ff>人間</color></b>の脳だ――わかるだろう？ 完全にクリーンな状態で持ち出すのは簡単じゃない。まあ、危険はないはずだが」'
0x1cffad0: bl       #0x1b64570 | 
0x1cffad8: ldr      x0, [x0, #0x780] | 0x418a780 '한때 그녀는 픽셀 타워 안에서 자신이 가진 ‘팔콘’에 대한 기억으로 새로운 ‘팔콘’을 만들어 냈다. 그러나 지금의 팔콘은 이미 오염되어 본래 모습을 알아볼 수 없게 되어 있었다. 더 이상 그녀의 기억 속에 있는 오빠가 아니라, 독립적으로 존재하는 하나의 ‘인간’이 되어 버린 것이다. 그 때문에 그녀는 더 이상 그를 알아보지 못했고, 심지어 그의 존재를 계속 유지하는 것마저 포기했다.\r\n“진짜 너는, 대체 어디에……”'
0x1cffadc: bl       #0x1b64570 | 
0x1cffae4: ldr      x0, [x0, #0x788] | 0x418a788 '770年が過ぎ、タワー組織はついにシミュレーション目標を達成した。技術の流出を防ぐため、彼らはデータを保存し、ピクセルタワーを停止させることを決定した。こうして、ピクセルタワーの消去プログラム「マザリノ境界」が起動された。\r\nすべてを呑み込む境界線のもと、<b><color=#00e4ff>人々</color></b>が築き上げたバベルの塔は、再び崩れ去った。'
0x1cffae8: bl       #0x1b64570 | 
0x1cffaf0: ldr      x0, [x0, #0x790] | 0x418a790 '她困于执念，苦寻无果，如今心荒如漠，绪乱如麻；'
0x1cffaf4: bl       #0x1b64570 | 
0x1cffafc: ldr      x0, [x0, #0x798] | 0x418a798 'Bound by obsession, she searched in vain - her heart now a barren waste, her mind a tangled knot of chaos.'
0x1cffb00: bl       #0x1b64570 | 
0x1cffb08: ldr      x0, [x0, #0x7a0] | 0x418a7a0 '於是，那一夜的營地繼續沉睡，'
0x1cffb0c: bl       #0x1b64570 | 
0x1cffb14: ldr      x0, [x0, #0x7a8] | 0x418a7a8 '曾经的她，在像素塔中用自己关于“隼”的记忆，制造了一个新的“隼”。但如今，这个隼已经被污染得面目全非，不再是她记忆里的兄长，而是一个独立存在的“<b><color=#00e4ff>人类</color></b>”，以至于她不再认识他，甚至放弃了继续维持他的存在。\r\n“你在哪……”'
0x1cffb18: bl       #0x1b64570 | 
0x1cffb20: ldr      x0, [x0, #0x7b0] | 0x418a7b0 '两道身影清醒着，踏上先驱者曾走过的路，'
0x1cffb24: bl       #0x1b64570 | 
0x1cffb2c: ldr      x0, [x0, #0x7b8] | 0x418a7b8 '彼女は執念に囚われ、追い求めてなお報われず、今や心は荒れ果て、思いは千々に乱れていた。'
0x1cffb30: bl       #0x1b64570 | 
0x1cffb38: ldr      x0, [x0, #0x7c0] | 0x418a7c0 '他誓守諾言，始終相伴，此刻忽得機緣，豁然通明。'
0x1cffb3c: bl       #0x1b64570 | 
0x1cffb44: ldr      x0, [x0, #0x7c8] | 0x418a7c8 '혼돈 속에서 진실의 희미한 형체가 모습을 드러내기 시작한다. 두 사람을 기다리고 있는 것은 과연 무엇일까?'
0x1cffb48: bl       #0x1b64570 | 
0x1cffb50: ldr      x0, [x0, #0x7d0] | 0x418a7d0 '她困於執念，苦尋無果，如今心荒如漠，緒亂如麻；'
0x1cffb54: bl       #0x1b64570 | 
0x1cffb5c: ldr      x0, [x0, #0x7d8] | 0x418a7d8 '그녀는 집념에 사로잡힌 채 헛되이 답을 찾아 헤맸고, 마음은 황무지처럼 메말라 감정이 실타래처럼 뒤엉켜 있었다.'
0x1cffb60: bl       #0x1b64570 | 
0x1cffb68: ldr      x0, [x0, #0x7e0] | 0x418a7e0 '七百七十年过去，塔组织已达到了模拟目标，他们决定保存数据，关闭像素塔，以防技术泄漏。于是，他们启动了像素塔的清扫程序——幽蓝边界。\r\n吞噬一切的境界线下，<b><color=#00e4ff>人类</color></b>建起的巴别塔再次倒塌。'
0x1cffb6c: bl       #0x1b64570 | 
0x1cffb74: ldr      x0, [x0, #0x7e8] | 0x418a7e8 '混沌之中，真相的虚影凝结，等待着二人的，又会是什么？'
0x1cffb78: bl       #0x1b64570 | 
0x1cffb80: ldr      x0, [x0, #0x7f0] | 0x418a7f0 '他誓守诺言，始终相伴，此刻忽得玄机，豁然通明。'
0x1cffb84: bl       #0x1b64570 | 
0x1cffb8c: ldr      x0, [x0, #0x7f8] | 0x418a7f8 '770 years later, the "Tower" organization had achieved the goal of its simulation. They decided to save the data and shut down the Pixel Tower to prevent technology leakage. And so they activated the Pixel Tower\'s cleanup protocol - the Mazarine End.\r\nBeneath the boundary that devours everything, the Tower of Babel that <b><color=#00e4ff>humanity</color></b> had raised collapsed again.'
0x1cffb90: bl       #0x1b64570 | 
0x1cffb98: ldr      x0, [x0, #0x800] | 0x418a800 '그렇게 그날 밤의 야영지는 계속 잠들어 있었고,'
0x1cffb9c: bl       #0x1b64570 | 
0x1cffba4: ldr      x0, [x0, #0x808] | 0x418a808 '誓いどおり、彼は変わらず傍らに寄り添い続けた。そして今、ふと一筋の機微をつかみ、すべてが俄かに開けていく。'
0x1cffba8: bl       #0x1b64570 | 
0x1cffbb0: ldr      x0, [x0, #0x810] | 0x418a810 'かつての彼女は、ピクセルタワーの中で自分の中にある「隼」の記憶を利用して、新たな「隼」を作り出した。しかし今や、その隼は原型を留めないほどに汚染され、もはや記憶の中の兄ではなく、独立した一人の「<b><color=#00e4ff>人間</color></b>」となってしまった。その結果、彼女は彼を認識できなくなり、彼という存在を維持することすら諦めてしまったのだ。\r\n「本当のあなたは……一体、どこにいるの……」'
0x1cffbb4: bl       #0x1b64570 | 
0x1cffbbc: ldr      x0, [x0, #0x818] | 0x418a818 '長く追い求めてきた真実の待つ場所へ向かって。'
0x1cffbc0: bl       #0x1b64570 | 
0x1cffbc8: ldr      x0, [x0, #0x820] | 0x418a820 'OpenSP'
0x1cffbcc: bl       #0x1b64570 | 
0x1cffbd4: ldr      x0, [x0, #0x828] | 0x418a828 'True to his vow, he remained by her side; a revelation strikes at this moment, laying all bare in sudden clarity.'
0x1cffbd8: bl       #0x1b64570 | 
0x1cffbe0: ldr      x0, [x0, #0x830] | 0x418a830 '「只要拿著就可以嗎，還是說需要進行某些操作？」\r\n「理論上說這東西是自動生效的，掏出來捏手裡就行。不過，我們不能保證它吸引來的完全都是我們的數據，畢竟<b><color=#00e4ff>人類</color></b>的大腦嘛——你懂得，纏點兒什麼，避免不了。」'
0x1cffbe4: bl       #0x1b64570 | 
0x1cffbec: ldr      x0, [x0, #0x838] | 0x418a838 '그는 자신의 약속을 지키며 줄곧 그녀의 곁을 지켰고, 지금 이 순간 문득 실마리를 얻어 모든 것이 환히 밝혀졌다.'
0x1cffbf0: bl       #0x1b64570 | 
0x1cffc00: bl       #0x1b647b8 | 
0x1cffc0c: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffc18: ldr      x8, [x8, #0x738] | 0x418a738 '“只要拿着就可以吗，还是说需要进行某些操作？”\r\n“理论上说这东西是自动生效的，掏出来捏手里就行。不过，我们不能保证它吸引来的完全都是我们的数据，毕竟<b><color=#00e4ff>人类</color></b>的大脑嘛——你懂得，缠点儿什么，避免不了。”'
0x1cffc28: ldr      x9, [x9, #0x830] | 0x418a830 '「只要拿著就可以嗎，還是說需要進行某些操作？」\r\n「理論上說這東西是自動生效的，掏出來捏手裡就行。不過，我們不能保證它吸引來的完全都是我們的數據，畢竟<b><color=#00e4ff>人類</color></b>的大腦嘛——你懂得，纏點兒什麼，避免不了。」'
0x1cffc38: ldr      x9, [x9, #0x6d8] | 0x418a6d8 '"Do I just hold it, or do I need to do something?"\r\n"Theoretically it activates on its own; just take it out and hold it. Still, we can\'t guarantee that everything it attracts is our data. <b><color=#00e4ff>Human</color></b> brains, you know - getting out cleanly isn\'t that easy. But it won\'t be dangerous, at least."'
0x1cffc48: ldr      x9, [x9, #0x778] | 0x418a778 '「手に持っているだけでいいのか？ それとも何か操作が必要か？」\r\n「理論上は自動で効力を発揮するはずだ、取り出して手に握っていればいい。ただ、引き寄せられるものが100%我々のデータだけとは保証できないがね。なにせ<b><color=#00e4ff>人間</color></b>の脳だ――わかるだろう？ 完全にクリーンな状態で持ち出すのは簡単じゃない。まあ、危険はないはずだが」'
0x1cffc58: ldr      x9, [x9, #0x6f0] | 0x418a6f0 "'그냥 들고 있으면 되는 거야, 아니면 무슨 조작이 필요한 거야?'\r\n'이론상 이건 자동으로 작동해. 꺼내서 손에 쥐고 있기만 하면 돼. 다만 이게 끌어오는 게 전부 우리 데이터라고는 장담할 수 없어. 인간의 뇌라니까. 알잖아. 깨끗하게 빼내는 게 그리 쉽지는 않거든. 그래도 위험한 일은 아니야.'"
0x1cffc7c: bl       #0x1b647b8 | 
0x1cffc88: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffc94: ldr      x8, [x8, #0x7a8] | 0x418a7a8 '曾经的她，在像素塔中用自己关于“隼”的记忆，制造了一个新的“隼”。但如今，这个隼已经被污染得面目全非，不再是她记忆里的兄长，而是一个独立存在的“<b><color=#00e4ff>人类</color></b>”，以至于她不再认识他，甚至放弃了继续维持他的存在。\r\n“你在哪……”'
0x1cffca0: ldr      x9, [x9, #0x708] | 0x418a708 '曾經的她，在像素塔中用自己關於“隼”的記憶，製造了一個新的“隼”。但如今，這個隼已經被污染得面目全非，不再是她記憶裡的兄長，而是一個獨立存在的“<b><color=#00e4ff>人類</color></b>”，以至於她不再認識他，甚至放棄了繼續維持他的存在。\r\n“你在哪……”'
0x1cffcb0: ldr      x9, [x9, #0x748] | 0x418a748 'Once, inside the Pixel Tower, she had used her memories of "Peregrinus" to create a new "Peregrinus." But now, that Peregrinus had been corrupted beyond recognition - no longer the brother she remembered, but an independent "<b><color=#00e4ff>human</color></b>" - she could no longer recognize him, and had even given up maintaining his existence.\r\n"Where is the real you..."'
0x1cffcc0: ldr      x9, [x9, #0x810] | 0x418a810 'かつての彼女は、ピクセルタワーの中で自分の中にある「隼」の記憶を利用して、新たな「隼」を作り出した。しかし今や、その隼は原型を留めないほどに汚染され、もはや記憶の中の兄ではなく、独立した一人の「<b><color=#00e4ff>人間</color></b>」となってしまった。その結果、彼女は彼を認識できなくなり、彼という存在を維持することすら諦めてしまったのだ。\r\n「本当のあなたは……一体、どこにいるの……」'
0x1cffcd0: ldr      x9, [x9, #0x780] | 0x418a780 '한때 그녀는 픽셀 타워 안에서 자신이 가진 ‘팔콘’에 대한 기억으로 새로운 ‘팔콘’을 만들어 냈다. 그러나 지금의 팔콘은 이미 오염되어 본래 모습을 알아볼 수 없게 되어 있었다. 더 이상 그녀의 기억 속에 있는 오빠가 아니라, 독립적으로 존재하는 하나의 ‘인간’이 되어 버린 것이다. 그 때문에 그녀는 더 이상 그를 알아보지 못했고, 심지어 그의 존재를 계속 유지하는 것마저 포기했다.\r\n“진짜 너는, 대체 어디에……”'
0x1cffcec: bl       #0x1b647b8 | 
0x1cffcf8: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffd04: ldr      x8, [x8, #0x7e0] | 0x418a7e0 '七百七十年过去，塔组织已达到了模拟目标，他们决定保存数据，关闭像素塔，以防技术泄漏。于是，他们启动了像素塔的清扫程序——幽蓝边界。\r\n吞噬一切的境界线下，<b><color=#00e4ff>人类</color></b>建起的巴别塔再次倒塌。'
0x1cffd18: ldr      x9, [x9, #0x710] | 0x418a710 '七百七十年過去，塔組織已達到了模擬目標，他們決定保存數據，關閉像素塔，以防技術洩漏。於是，他們啟動了像素塔的清掃程序——幽藍邊界。\r\n吞噬一切的境界線下，<b><color=#00e4ff>人類</color></b>建起的巴別塔再次倒塌。'
0x1cffd28: ldr      x9, [x9, #0x7f8] | 0x418a7f8 '770 years later, the "Tower" organization had achieved the goal of its simulation. They decided to save the data and shut down the Pixel Tower to prevent technology leakage. And so they activated the Pixel Tower\'s cleanup protocol - the Mazarine End.\r\nBeneath the boundary that devours everything, the Tower of Babel that <b><color=#00e4ff>humanity</color></b> had raised collapsed again.'
0x1cffd38: ldr      x9, [x9, #0x788] | 0x418a788 '770年が過ぎ、タワー組織はついにシミュレーション目標を達成した。技術の流出を防ぐため、彼らはデータを保存し、ピクセルタワーを停止させることを決定した。こうして、ピクセルタワーの消去プログラム「マザリノ境界」が起動された。\r\nすべてを呑み込む境界線のもと、<b><color=#00e4ff>人々</color></b>が築き上げたバベルの塔は、再び崩れ去った。'
0x1cffd48: ldr      x9, [x9, #0x740] | 0x418a740 '770년이 흐른 뒤, 탑 조직은 시뮬레이션의 목표에 도달했다. 그들은 기술 유출을 막기 위해 데이터를 보존하고 픽셀 타워를 폐쇄하기로 결정했다. 그리고 픽셀 타워의 정리 프로그램——마자린 엔드——를 가동했다.\r\n모든 것을 집어삼키는 경계선 아래에서, <b><color=#00e4ff>인간</color></b>들이 세운 바벨탑은 다시 무너져 내렸다.'
0x1cffd60: ldr      x9, [x9, #0x720] | 0x418a720 'Open'
0x1cffd70: ldr      x19, [x19, #0x820] | 0x418a820 'OpenSP'
0x1cffd78: bl       #0x3c10910 | UnityEngine.Animator$$StringToHash
0x1cffd90: bl       #0x3c10910 | UnityEngine.Animator$$StringToHash
0x1cffda8: bl       #0x1b64614 | 
0x1cffdb8: bl       #0x1b647b8 | 
0x1cffdc4: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffdd0: ldr      x8, [x8, #0x790] | 0x418a790 '她困于执念，苦寻无果，如今心荒如漠，绪乱如麻；'
0x1cffddc: ldr      x9, [x9, #0x7d0] | 0x418a7d0 '她困於執念，苦尋無果，如今心荒如漠，緒亂如麻；'
0x1cffdec: ldr      x9, [x9, #0x798] | 0x418a798 'Bound by obsession, she searched in vain - her heart now a barren waste, her mind a tangled knot of chaos.'
0x1cffdfc: ldr      x9, [x9, #0x7b8] | 0x418a7b8 '彼女は執念に囚われ、追い求めてなお報われず、今や心は荒れ果て、思いは千々に乱れていた。'
0x1cffe0c: ldr      x9, [x9, #0x7d8] | 0x418a7d8 '그녀는 집념에 사로잡힌 채 헛되이 답을 찾아 헤맸고, 마음은 황무지처럼 메말라 감정이 실타래처럼 뒤엉켜 있었다.'
0x1cffe28: bl       #0x1b646a8 | 
0x1cffe40: bl       #0x1b647b8 | 
0x1cffe4c: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffe58: ldr      x8, [x8, #0x7f0] | 0x418a7f0 '他誓守诺言，始终相伴，此刻忽得玄机，豁然通明。'
0x1cffe68: ldr      x9, [x9, #0x7c0] | 0x418a7c0 '他誓守諾言，始終相伴，此刻忽得機緣，豁然通明。'
0x1cffe78: ldr      x9, [x9, #0x828] | 0x418a828 'True to his vow, he remained by her side; a revelation strikes at this moment, laying all bare in sudden clarity.'
0x1cffe88: ldr      x9, [x9, #0x808] | 0x418a808 '誓いどおり、彼は変わらず傍らに寄り添い続けた。そして今、ふと一筋の機微をつかみ、すべてが俄かに開けていく。'
0x1cffe98: ldr      x9, [x9, #0x838] | 0x418a838 '그는 자신의 약속을 지키며 줄곧 그녀의 곁을 지켰고, 지금 이 순간 문득 실마리를 얻어 모든 것이 환히 밝혀졌다.'
0x1cffeac: bl       #0x1b646a8 | 
0x1cffec8: bl       #0x1b647b8 | 
0x1cffed4: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cffee0: ldr      x8, [x8, #0x7e8] | 0x418a7e8 '混沌之中，真相的虚影凝结，等待着二人的，又会是什么？'
0x1cffef0: ldr      x9, [x9, #0x718] | 0x418a718 '混沌之中，真相的虛影凝結，等待著二人的，又會是什麼？'
0x1cfff00: ldr      x9, [x9, #0x750] | 0x418a750 'From the swirling chaos, the shadowy phantom of truth begins to take shape. What fate, then, lies in wait for them both?'
0x1cfff10: ldr      x9, [x9, #0x6c8] | 0x418a6c8 '混沌の中、真実の幻影が次第に形を結び始める。この先、一体何が二人を待ち受けているのだろうか？'
0x1cfff20: ldr      x9, [x9, #0x7c8] | 0x418a7c8 '혼돈 속에서 진실의 희미한 형체가 모습을 드러내기 시작한다. 두 사람을 기다리고 있는 것은 과연 무엇일까?'
0x1cfff34: bl       #0x1b646a8 | 
0x1cfff60: bl       #0x1b64614 | 
0x1cfff70: bl       #0x1b647b8 | 
0x1cfff7c: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1cfff88: ldr      x8, [x8, #0x768] | 0x418a768 '于是，那一夜的营地继续沉睡，'
0x1cfff94: ldr      x9, [x9, #0x7a0] | 0x418a7a0 '於是，那一夜的營地繼續沉睡，'
0x1cfffa4: ldr      x9, [x9, #0x700] | 0x418a700 'Thus, the camp slept on through the night,'
0x1cfffb4: ldr      x9, [x9, #0x6e8] | 0x418a6e8 'そして、野営地が夜の眠りに包まれる中、'
0x1cfffc4: ldr      x9, [x9, #0x800] | 0x418a800 '그렇게 그날 밤의 야영지는 계속 잠들어 있었고,'
0x1cfffe0: bl       #0x1b646a8 | 
0x1cffff8: bl       #0x1b647b8 | 
0x1d00004: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1d00010: ldr      x8, [x8, #0x7b0] | 0x418a7b0 '两道身影清醒着，踏上先驱者曾走过的路，'
0x1d00020: ldr      x9, [x9, #0x728] | 0x418a728 '兩道身影清醒著，踏上先驅者曾走過的路，'
0x1d00030: ldr      x9, [x9, #0x770] | 0x418a770 'while two wakeful souls embarked upon the path trodden by forerunners,'
0x1d00040: ldr      x9, [x9, #0x6f8] | 0x418a6f8 '眠らぬ二人は、先人たちの辿った道へと踏み出した。'
0x1d00050: ldr      x9, [x9, #0x758] | 0x418a758 '두 사람만이 깨어 선구자들이 걸었던 길에 발을 내디뎠다.'
0x1d00064: bl       #0x1b646a8 | 
0x1d00080: bl       #0x1b647b8 | 
0x1d0008c: bl       #0x1cd9064 | Phigros2.Utils.MultiLanguageText.MultiLanguageTextString$$.ctor
0x1d00098: ldr      x8, [x8, #0x760] | 0x418a760 '向着他们渴望的真相所在之处走去。'
0x1d000a8: ldr      x9, [x9, #0x6e0] | 0x418a6e0 '向著他們渴望的真相所在之處走去。'
0x1d000b8: ldr      x9, [x9, #0x730] | 0x418a730 'walking towards the place where their long-sought truth awaited.'
0x1d000c8: ldr      x9, [x9, #0x818] | 0x418a818 '長く追い求めてきた真実の待つ場所へ向かって。'
0x1d000d8: ldr      x9, [x9, #0x6d0] | 0x418a6d0 '그들이 그토록 갈망하던 진실이 있는 곳을 향해 걸어갔다.'
0x1d000ec: bl       #0x1b646a8 | 
